"""Complete source-limited pages and clean known translation defects.
The raw crawl in catalog.json is immutable evidence. Prices, programmes and
source-language differences are retained, not silently reconciled.
"""
import json,re,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'src/data'
c=json.loads((D/'catalog.json').read_text()); o=json.loads((D/'translation-overrides.json').read_text())
langs=['en','tr','fr','de','nl','ru']; changes=[]
def patch(id,key,values,reason):
    for lang,value in zip(langs,values):
        prev=o.setdefault(id,{}).setdefault(lang,{}).get(key)
        if prev!=value:
            o[id][lang][key]=value;changes.append({'id':id,'locale':lang,'field':key,'reason':reason})
def words(values,lang): return values[langs.index(lang)]

