# Correct known machine-translation false friends and place names, preserving all figures and tables.
glossary={
'tr':{'Kılavuz ve Sürücü':'rehber ve şoför','kılavuz ve sürücü':'rehber ve şoför','Biblical':'İncil’de adı geçen','Virgin Mary Evi':'Meryem Ana Evi','The Virgin Mary':'Meryem Ana','House of the Virgin Mary':'Meryem Ana Evi','Sanliurfa':'Şanlıurfa','Gobeklitepe':'Göbeklitepe','Haleplibahce':'Haleplibahçe','Cave Hotel':'mağara otel','yurtiçi uçuşlar':'iç hat uçuşları','Yurtiçi uçuşlar':'İç hat uçuşları','Uluslararası uçak bileti':'Uluslararası uçak bileti','Peygamberlerin Yasasını':'Elçilerin İşleri kitabını','Polio Çeşmesi':'Pollio Çeşmesi','Mosaic Müzesi':'Mozaik Müzesi','bakırsmiths ve carper yapımcıları':'bakırcılar ve halıcılar','Euphrates':'Fırat','Jacob’ın Well’i':'Yakup Kuyusu','Jacob\'ın Well\'i':'Yakup Kuyusu'},
'nl':{'stuurprogramma':'chauffeur','overdrachten':'transfers','Semi particuliere begeleiding':'Begeleiding in een kleine groep','Cappadocia':'Cappadocië','Izmir':'İzmir','Hotel en luchthaven extra\'s':'Extra kosten in hotel en luchthaven'},
'de':{'Tipps für Guide und Fahrer':'Trinkgelder für Reiseleitung und Fahrer','Halbprivates Guiding':'Reiseleitung in kleiner Gruppe','Cave Hotel':'Höhlenhotel'},
'ru':{'Советы для гида и водителя':'Чаевые гиду и водителю','Советы гиду и водителю':'Чаевые гиду и водителю','Фонтан Полиомиелита':'Фонтан Поллио','фонтан Полиомиелита':'фонтан Поллио','вы пропустите строки':'вы пройдёте без очереди','Cave Hotel':'пещерном отеле','Отель и аэропорт дополнительные':'Дополнительные расходы в отеле и аэропорту'},
'fr':{'hotel troglodyte':'hôtel troglodyte','hotel et aéroport':'hôtel et aéroport'},
'en':{'Vigin Mary':'Virgin Mary','veichle':'vehicle','peacefull':'peaceful','non-toursity':'quiet','non-toursity':'quiet','Scolastica':'Scholastica','Polio Fountain':'Pollio Fountain','Memnius':'Memmius','Beveages':'Beverages','Accomodation':'Accommodation','accomodation':'accommodation'},
}
for id,translations in o.items():
    for l,v in translations.items():
        for key in ['title','description','bodyHtml']:
            if key not in v:continue
            before=v[key];after=before
            # Text-node-only replacements leave source URLs and image paths intact.
            for old,new in glossary.get(l,{}).items():
                after=''.join(part if part.startswith('<') else part.replace(old,new) for part in re.split('(<[^>]*>)',after))
            if before!=after:
                assert re.findall(r'\d+',before)==re.findall(r'\d+',after),(id,l)
                v[key]=after;changes.append({'id':id,'locale':l,'field':key,'reason':'Reviewed terminology / false-friend correction'})

